// Using CGAL for robust polygon boolean operations
    using Kernel = CGAL::Exact_predicates_inexact_constructions_kernel;
    using Polygon_2 = CGAL::Polygon_2<Kernel>;
    using Polygon_with_holes_2 = CGAL::Polygon_with_holes_2<Kernel>;
    using Polygon_set_2 = CGAL::Polygon_set_2<Kernel>;

    // Convert input polygons to CGAL format
    auto convert_to_cgal = [](const Polygon2d& poly) {
        Polygon_2 cgal_poly;
        for (const auto& point : poly.outer()) {
            cgal_poly.push_back(Kernel::Point_2(point.x(), point.y()));
        }
        return cgal_poly;
    };

    Polygon_2 cgal_p1 = convert_to_cgal(P1);
    Polygon_2 cgal_p2 = convert_to_cgal(P2);

    // Create polygon set and compute difference
    Polygon_set_2 pset;
    pset.insert(cgal_p1);
    pset.difference(cgal_p2);

    // Convert result back to output format
    std::vector<PolygonWithHoles2d> result;
    std::list<Polygon_with_holes_2> cgal_result;
    pset.polygons_with_holes(std::back_inserter(cgal_result));

    for (const auto& cgal_poly_with_holes : cgal_result) {
        PolygonWithHoles2d poly_with_holes;

        // Convert outer boundary
        Polygon2d outer;
        for (const auto& point : cgal_poly_with_holes.outer_boundary()) {
            outer.outer().emplace_back(point.x(), point.y());
        }
        poly_with_holes.set_outer(outer);

        // Convert holes
        for (const auto& hole : cgal_poly_with_holes.holes()) {
            Polygon2d hole_poly;
            for (const auto& point : hole) {
                hole_poly.outer().emplace_back(point.x(), point.y());
            }
            poly_with_holes.add_hole(hole_poly);
        }

        result.push_back(poly_with_holes);
    }

    return result;
    // END_CODE

